  }

  // Orders
  const orders = db.prepare(\"SELECT * FROM orders WHERE customer_id=? AND source_skill='tau2Retail'\").all(u.user_id);
  for (const o of orders) {
    console.log('  ORDER:', o.order_id, 'status:', o.status);
    const items = db.prepare('SELECT * FROM order_items WHERE order_id=?').all(o.order_id);
    for (const oi of items) {
      console.log('    ITEM:', oi.item_id, oi.name, 'price:', oi.unit_price, 'product_id:', oi.product_id);
    }
    const payments = db.prepare('SELECT * FROM order_payments WHERE order_id=?').all(o.order_id);
    for (const p of payments) {
      console.log('    PAYMENT:', p.transaction_type, p.amount, p.payment_method_id);
    }
  }
}
db.close();
