const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// Search for any user with zip 94109
const users = db.prepare(\"SELECT * FROM users WHERE address_json LIKE '%94109%'\").all();
for (const u of users) {
  const addr = JSON.parse(u.address_json || '{}');
  console.log('USER:', u.user_id, u.name, u.email, 'zip:', addr.zip);
}

// Also search for the order ORD-5B048F
console.log('\n--- Searching for order ORD-5B048F or similar ---');
const orders = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%5B048F%'\").all();
for (const o of orders) {
  console.log('ORDER:', o.order_id, 'status:', o.status, 'customer:', o.customer_id);
}

// Search for item ITEM-63F395
console.log('\n--- Searching for item ITEM-63F395 or similar ---');
const items = db.prepare(\"SELECT * FROM order_items WHERE item_id LIKE '%63F395%'\").all();
for (const i of items) {
  console.log('ITEM:', i.item_id, i.name, 'order:', i.order_id);
}

// Search for product PROD-2DBA15
console.log('\n--- Searching for product PROD-2DBA15 or similar ---');
const prods = db.prepare(\"SELECT * FROM products WHERE product_id LIKE '%2DBA15%'\").all();
for (const p of prods) {
  console.log('PRODUCT:', p.product_id, p.name);
}

// Search for Anker Portable Bluetooth Speaker in order items
console.log('\n--- Searching for Anker speaker in order items ---');
const speakerItems = db.prepare(\"SELECT oi.*, o.customer_id, o.status FROM order_items oi JOIN orders o ON oi.order_id=o.order_id WHERE oi.name LIKE '%Speaker%' OR oi.name LIKE '%Anker%'\").all();
for (const si of speakerItems) {
  console.log('SPEAKER ITEM:', si.item_id, si.name, 'order:', si.order_id, 'status:', si.status, 'customer:', si.customer_id);
}

// Search for Wireless Ergonomic Mouse
console.log('\n--- Searching for Wireless Ergonomic Mouse ---');
const mouseProds = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Ergonomic%Mouse%' OR name LIKE '%Wireless%Mouse%'\").all();
for (const p of mouseProds) {
  console.log('PRODUCT:', p.product_id, p.name);
}

db.close();
"

